// Tres formas de limitar, con un reloj falso para poder probarlas al instante.
class VentanaFija {                      // cuenta por bloque de tiempo; al cambiar de bloque vuelve a cero
  constructor(limite, ventanaMs) { this.limite = limite; this.ventana = ventanaMs; this.bloque = -1; this.n = 0; }
  permitir(t) { const b = Math.floor(t / this.ventana); if (b !== this.bloque) { this.bloque = b; this.n = 0; } return this.n < this.limite ? (this.n++, true) : false; }
}
class VentanaDeslizante {                // guarda la hora de cada pedido aceptado y cuenta solo los de los últimos ventanaMs
  constructor(limite, ventanaMs) { this.limite = limite; this.ventana = ventanaMs; this.horas = []; }
  permitir(t) { while (this.horas.length && this.horas[0] <= t - this.ventana) this.horas.shift(); if (this.horas.length < this.limite) { this.horas.push(t); return true; } return false; }
}
class BaldeDeFichas {                    // token bucket: capacidad C, se rellena a R fichas por segundo
  constructor(capacidad, porSegundo) { this.c = capacidad; this.r = porSegundo; this.fichas = capacidad; this.ultimo = 0; }
  permitir(t) { this.fichas = Math.min(this.c, this.fichas + (t - this.ultimo) / 1000 * this.r); this.ultimo = t; if (this.fichas >= 1) { this.fichas -= 1; return true; } return false; }
  segundosHastaFicha() { return Math.max(0, (1 - this.fichas) / this.r); }
}

// Prueba: límite de 10 pedidos por minuto (el balde: capacidad 10, 10 fichas por 60 s = 1 ficha cada 6 s)
function correr(nombre, lim, pedidos) { let ok = 0; const aceptados = []; for (const t of pedidos) if (lim.permitir(t)) { ok++; aceptados.push(Math.round(t / 100) / 10); } return { nombre, ok, aceptados }; }
const rafaga = (desde, n) => Array.from({ length: n }, (_, i) => desde + i * 50);   // n pedidos, uno cada 50 ms
// A: 10 pedidos al final del minuto 0 (t = 59 s) y 10 al inicio del minuto 1 (t = 60 s)
const borde = [...rafaga(59000, 10), ...rafaga(60000, 10)];
for (const r of [correr('ventana fija 10/min', new VentanaFija(10, 60000), borde),
                 correr('ventana deslizante 10/min', new VentanaDeslizante(10, 60000), borde),
                 correr('balde 10 fichas, 1 cada 6 s', new BaldeDeFichas(10, 1 / 6), borde)])
  console.log(r.nombre.padEnd(30), 'aceptó', String(r.ok).padStart(2), 'de 20 en 1 segundo');

// B: un cliente tranquilo (un pedido cada 10 s durante 2 minutos) que a los 65 s junta 8 pedidos de golpe
const tranquilo = Array.from({ length: 12 }, (_, i) => i * 10000);
const mixto = [...tranquilo, ...rafaga(65000, 8)].sort((a, b) => a - b);
for (const r of [correr('ventana deslizante 10/min', new VentanaDeslizante(10, 60000), mixto),
                 correr('balde 10 fichas, 1 cada 6 s', new BaldeDeFichas(10, 1 / 6), mixto)]) {
  const deLaRafaga = r.aceptados.filter((t) => t >= 65 && t < 66).length;
  console.log(r.nombre.padEnd(30), 'aceptó', String(r.ok).padStart(2), 'de', mixto.length, '| de la ráfaga de 8 pasaron', deLaRafaga);
}

